insert into public.stories (id, title, country, category, locale, sample_image_id, body, author_name, status, is_sample, approved_at) values
('00000000-0000-4000-8000-000000000001', 'Tea above the domes of the Medina', 'tunisia', 'story', 'en', 'tn-dest-medina-tunis', 'Rooftop terraces around the Medina offer views across domes, narrow lanes and the minaret of the Zitouna Mosque. Mint tea provides a quiet pause after walking through the covered souks. Late afternoon brings softer light to the white walls and tiled courtyards. Visitors can ask before photographing people, keep passageways clear and leave time to find their way back through the small streets. Comfortable shoes are useful on the uneven paving.', 'IEEE Exchange Team', 'approved', true, '2026-11-17T12:00:00Z'),
('00000000-0000-4000-8000-000000000002', 'Morning light on the Pearling Path', 'bahrain', 'photo', 'en', 'bh-dest-pearling-path', 'The Pearling Path links houses and public spaces in Muharraq with the history of Bahrain’s pearl trade. Morning light reveals details in doorways, shaded passages and restored walls. A slow walk leaves room to read the interpretation panels and notice the relationship between homes and neighbourhood streets. Opening hours vary between buildings, so checking access before setting out is useful. Carry water, respect residential entrances and ask permission before including people in photographs.', 'IEEE Exchange Team', 'approved', true, '2026-11-17T12:00:00Z'),
('00000000-0000-4000-8000-000000000003', 'Une journée à Sidi Bou Saïd, pas à pas', 'tunisia', 'diary', 'fr', 'tn-dest-sidi-bou-said', 'Les ruelles de Sidi Bou Saïd invitent à marcher lentement entre les façades blanches et les portes bleues. Depuis les hauteurs, le regard rejoint la baie et les jardins voisins. Une pause à une terrasse permet de profiter du paysage sans presser la visite. Les pavés peuvent être irréguliers et les montées demandent des chaussures confortables. Il est préférable de respecter les entrées privées et de demander avant de photographier les habitants ou leurs boutiques.', 'IEEE Exchange Team', 'approved', true, '2026-11-17T12:00:00Z'),
('00000000-0000-4000-8000-000000000004', 'من المقروض إلى اللقيمات', 'both', 'anecdote', 'ar', 'tn-sweet-makroudh', 'تتيح الحلويات فرصة هادئة للتعرف على عادات الضيافة في تونس والبحرين. يقدم المقروض غالبا مع الشاي أو القهوة، وتظهر اللقيمات على موائد اللقاءات العائلية والمناسبات. تختلف الوصفات وطرق التقديم بين البيوت والمحلات، لذلك يمكن السؤال عن المكونات قبل التذوق، خاصة عند وجود حساسية غذائية. لا تختصر قطعة حلوى ثقافة بلد كامل، لكنها تفتح حديثا عن المطبخ والذاكرة اليومية. ومن اللطيف مشاركة طبق صغير وترك الوقت للاستماع إلى أسماء الحلويات وكيفية إعدادها واحترام تنوع الأذواق.', 'IEEE Exchange Team', 'approved', true, '2026-11-17T12:00:00Z'),
('00000000-0000-4000-8000-000000000005', 'The Tree of Life at sunset', 'bahrain', 'photo', 'en', 'bh-dest-tree-of-life', 'The Tree of Life stands in an open desert setting where the changing light becomes part of the visit. Near sunset, its branches make a clear silhouette against the sky. The surrounding ground deserves the same care as the tree itself: stay within permitted areas, avoid climbing and take all litter away. Water and sun protection remain useful even late in the day. Arrange transport in advance and allow enough time for the return journey.', 'IEEE Exchange Team', 'approved', true, '2026-11-17T12:00:00Z'),
('00000000-0000-4000-8000-000000000006', 'Barcha, wayed: one word, two accents', 'both', 'anecdote', 'en', 'cg-calligraphy', 'Everyday expressions can introduce a conversation about language without turning it into a vocabulary test. Barcha in Tunisian speech and wayed in Bahraini speech can both express the idea of much or many, depending on context. Pronunciation and usage vary between speakers, so listening matters more than memorising a single translation. An exchange activity might invite participants to offer a short example, explain when they use it and compare friendly greetings at their own pace.', 'IEEE Exchange Team', 'approved', true, '2026-11-17T12:00:00Z')
